layers.vertex:
attribute vec3 aO; attribute vec2 aP; attribute float aT, aV; uniform float uTime; varying vec2 vQ; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){ if (aV < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float u = uTime - aT, k = eox(clamp(u/.3, 0., 1.)), R = mix(.08, 0.58, k);
      vU = u; vK = aP.y < -.5 ? 1. : 0.;
      if (aP.y < -.5){                                           // orbit line: flat ring quad in the horizontal plane
        float S = .72; vQ = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, 0.95, -position.y*S), 1.); return; }
      float ang = aP.x + aP.y*3.14159 + uTime*.7;                  // two shards sit opposite each other on the line
      vec3 c = aO + vec3(cos(ang)*R, 0.95 + .25*(1. - k), sin(ang)*R);
      vec4 mv = viewMatrix*vec4(c, 1.); vec2 q = position.xy; mv.xy += q*vec2(.07, .13);
      vQ = q; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uCW; varying vec2 vQ; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float lineCore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float pk = vU < .033 ? 2. : 1. + .8*exp(-max(vU - .033, 0.)*10.);
      vec3 o;
      if (vK > .5){
        // thin orbit line: fine core + narrow soft halo, energy drifting slowly in the shards' direction
        float r = length(vQ), a = atan(vQ.y, vQ.x), R = mix(.08, 0.58, eox(clamp(vU/.3, 0., 1.)));
        float flow = .6 + .4*pow(.5 + .5*sin(a*3. + uTime*1.4), 2.);
        float line = lineCore(r - R, .004)*.55 + exp(-pow((r - R)/.025, 2.))*.1;
        o = (uCW*line*flow + mix(uCW, vec3(1.), .5)*lineCore(r - R, .0025)*.25*flow)*pk;
        o *= smoothstep(.72, .66, r);
      } else {
        float d = abs(vQ.x) + abs(vQ.y)*.55 - .55;                          // elongated diamond (the icon's crystal)
        float edge = lineCore(d, .07), fill = .18*smoothstep(.05, -.1, d), facet = .5*lineCore(vQ.x, .05)*smoothstep(0., -.2, d);
        float halo = exp(-dot(vQ, vQ)*5.)*.12;
        o = (uCW*(edge*.8 + fill + halo) + mix(uCW, vec3(1., .96, 1.), .6)*facet*.6)*pk*(.85 + .15*sin(uTime*2. + vQ.y));
        o *= smoothstep(1., .8, length(vQ));                                // reaches zero before the quad edge
      }
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }
